import React, { useState } from 'react';
import './WelcomeModal.css';
import welcomeStartModel from '../assets/welcomesstartmodel.svg';
import startnewModel from '../assets/startnewmodel.svg';

const WelcomeModal = ({ isOpen, onClose }) => {
  const [step, setStep] = useState(1);

  if (!isOpen) return null;

  const handleNext = () => {
    setStep(2);
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h2>Start</h2>
          <p>
            {step === 1 
              ? "Welcome to Agent QA! You can start your journey with QA Agent now to get your GUI & API testing done!"
              : "You can also start we chat from other option as shown below"}
          </p>
        </div>

        <div className="image-container">
          <img 
            src={step === 1 ? welcomeStartModel : startnewModel} 
            alt="Welcome Start Model" 
            className="welcome-image" 
          />
        </div>

        <div className="prompt-section">
          <div className="prompt-label">
            {step === 1 ? "Enter your prompt" : "Click On Start New"}
          </div>
          <div className="prompt-text">
            {step === 1 
              ? "To start new chat for generating test cases"
              : "To begin generating test cases"}
          </div>
          {step === 1 ? (
            <button className="next-button" onClick={handleNext}>
              Next
            </button>
          ) : (
            <button className="next-button" onClick={onClose}>
              Got it
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default WelcomeModal;
